CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, display_name text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id text REFERENCES users(id),csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces(id text PRIMARY KEY,name text NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(workspace_id text REFERENCES workspaces(id),user_id text REFERENCES users(id),role text CHECK(role IN ('admin','agent','viewer')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS conversations(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),owner_id text NOT NULL REFERENCES users(id),title text NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS tickets(id text PRIMARY KEY,number serial,workspace_id text NOT NULL REFERENCES workspaces(id),title text NOT NULL,description text NOT NULL,priority text NOT NULL CHECK(priority IN ('low','medium','high')),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved','closed')),assignee_id text,created_by text NOT NULL,source_conversation_id text,version integer NOT NULL DEFAULT 1,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,assignee_id) REFERENCES memberships(workspace_id,user_id),FOREIGN KEY(workspace_id,created_by) REFERENCES memberships(workspace_id,user_id),FOREIGN KEY(workspace_id,source_conversation_id) REFERENCES conversations(workspace_id,id));
CREATE INDEX IF NOT EXISTS tickets_filter ON tickets(workspace_id,status,updated_at DESC);
CREATE TABLE IF NOT EXISTS ticket_comments(id text PRIMARY KEY,workspace_id text NOT NULL,ticket_id text NOT NULL,author_id text REFERENCES users(id),body text NOT NULL,created_at timestamptz DEFAULT now(),FOREIGN KEY(workspace_id,ticket_id) REFERENCES tickets(workspace_id,id));
CREATE TABLE IF NOT EXISTS audit_logs(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),actor_id text REFERENCES users(id),entity_type text NOT NULL,entity_id text NOT NULL,action text NOT NULL,before_data jsonb,after_data jsonb,request_id text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_runs(id text PRIMARY KEY,workspace_id text NOT NULL,conversation_id text NOT NULL,owner_id text REFERENCES users(id),status text NOT NULL,model text NOT NULL,prompt_version text DEFAULT 'v1',content text DEFAULT '',question text NOT NULL,client_request_id text NOT NULL,error_code text,usage jsonb,latency integer,regenerated_from text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(workspace_id,id),UNIQUE(conversation_id,client_request_id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_run ON ai_runs(conversation_id) WHERE status IN ('pending','retrieving','generating');
CREATE TABLE IF NOT EXISTS messages(id text PRIMARY KEY,workspace_id text NOT NULL,conversation_id text NOT NULL,role text NOT NULL,content text NOT NULL DEFAULT '',status text NOT NULL,run_id text NOT NULL REFERENCES ai_runs(id),created_at timestamptz DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id));
CREATE INDEX IF NOT EXISTS messages_order ON messages(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS documents(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),title text NOT NULL,active_version_id text,deleted_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS document_versions(id text PRIMARY KEY,workspace_id text NOT NULL,document_id text NOT NULL,version_no integer NOT NULL,body text NOT NULL,content_hash text NOT NULL,status text NOT NULL DEFAULT 'pending',error text,embedding_model text,embedding_dimension integer,created_at timestamptz DEFAULT now(),UNIQUE(document_id,version_no),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,document_id) REFERENCES documents(workspace_id,id));
CREATE TABLE IF NOT EXISTS document_chunks(id text PRIMARY KEY,workspace_id text NOT NULL,version_id text NOT NULL,chunk_index integer NOT NULL,heading text NOT NULL,start_offset integer NOT NULL,end_offset integer NOT NULL,text text NOT NULL,embedding vector NOT NULL,UNIQUE(version_id,chunk_index),FOREIGN KEY(workspace_id,version_id) REFERENCES document_versions(workspace_id,id));
CREATE INDEX IF NOT EXISTS chunks_scope ON document_chunks(workspace_id,version_id);
CREATE TABLE IF NOT EXISTS message_citations(id text PRIMARY KEY,workspace_id text NOT NULL,message_id text NOT NULL,chunk_id text NOT NULL REFERENCES document_chunks(id),version_id text NOT NULL,label text NOT NULL,quoted_text text NOT NULL,FOREIGN KEY(workspace_id,message_id) REFERENCES messages(workspace_id,id),FOREIGN KEY(workspace_id,version_id) REFERENCES document_versions(workspace_id,id));
CREATE TABLE IF NOT EXISTS jobs(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),type text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer DEFAULT 0,run_after timestamptz DEFAULT now(),locked_until timestamptz,locked_by text,last_error text,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_claim ON jobs(status,run_after);
CREATE TABLE IF NOT EXISTS tool_drafts(id text PRIMARY KEY,workspace_id text NOT NULL,conversation_id text NOT NULL,run_id text REFERENCES ai_runs(id),created_by text NOT NULL REFERENCES users(id),payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',version integer DEFAULT 1,ticket_id text UNIQUE REFERENCES tickets(id),expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now(),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id));
CREATE TABLE IF NOT EXISTS idempotency_records(workspace_id text NOT NULL,actor_id text NOT NULL,operation text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(workspace_id,actor_id,operation,key));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_run_per_user ON ai_runs(owner_id) WHERE status IN ('pending','retrieving','generating');
CREATE TABLE IF NOT EXISTS ai_usage_limits(scope text NOT NULL,window_start timestamptz NOT NULL,used integer NOT NULL,PRIMARY KEY(scope,window_start));
